-- Ecclesia initial migration (Sprint 1.3 - Database Foundation)
--
-- Rebuilt to match db/schema.prisma exactly, which was itself rebuilt
-- against the real Blueprint/PRD text in docs/. See db/DESIGN_NOTES.md for
-- the evidence behind every table/column below, tagged [BLUEPRINT-EXACT]
-- or [PRD-DERIVED], and for the open questions still outstanding. This
-- file was NOT generated by `prisma migrate dev` against a live database
-- (no PostgreSQL instance or package registry access was available in the
-- sandbox that authored it) - it must be validated for real before being
-- treated as trustworthy:
--
--   1. `prisma validate` (confirms this SQL and schema.prisma agree)
--   2. Apply to a real local PostgreSQL instance and confirm no errors
--   3. `prisma migrate diff` against the applied database, confirm empty
--
-- Implements, per db/migrations/README.md's commitment:
--   - the seven bounded-context Postgres schemas (Blueprint §7.2)
--   - Row-Level Security policies (Blueprint §7.3)
--   - the append-only Financial Transaction event model (Blueprint §7.4)
--   - the temporal GROUP_MEMBERSHIP model (Blueprint §7.5)

-- ===========================================================================
-- Extensions
-- ===========================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ===========================================================================
-- Schemas - all seven bounded contexts (Blueprint §7.2)
-- ===========================================================================

CREATE SCHEMA IF NOT EXISTS people;
CREATE SCHEMA IF NOT EXISTS pastoral_care;
CREATE SCHEMA IF NOT EXISTS ministry;
CREATE SCHEMA IF NOT EXISTS gatherings;
CREATE SCHEMA IF NOT EXISTS stewardship;
CREATE SCHEMA IF NOT EXISTS insights;
CREATE SCHEMA IF NOT EXISTS platform;

-- ===========================================================================
-- Enums
-- ===========================================================================

CREATE TYPE people."Role" AS ENUM (
  'RESIDENT_PASTOR', 'ACTING_RESIDENT_PASTOR', 'ASSISTANT_PASTOR',
  'BACENTA_LEADER', 'BASONTA_LEADER', 'TREASURER', 'WORKER', 'MEMBER',
  'VISITOR', 'ADMIN', 'COUNCIL_OVERSEER'
);

-- [BLUEPRINT-EXACT] PRD §12.6 - PASTORAL_CARE (Bacenta) / MINISTRY
-- (Basonta) only, no Cluster type.
CREATE TYPE people."GroupType" AS ENUM ('PASTORAL_CARE', 'MINISTRY');

-- [BLUEPRINT-EXACT] PRD §12.6's Group lifecycle state diagram.
CREATE TYPE people."GroupLifecycleStatus" AS ENUM ('ACTIVE', 'SPLITTING', 'MERGING', 'ARCHIVED');

-- [BLUEPRINT-EXACT] PRD §12.5 / BR-PPL-03's exact 7-state list.
CREATE TYPE people."LifecycleStage" AS ENUM (
  'VISITOR', 'FIRST_TIME_GUEST', 'FOLLOW_UP', 'LAPSED',
  'ASSIGNED_TO_BACENTA', 'SIX_WEEKS_PARTICIPATION', 'MEMBER'
);

CREATE TYPE pastoral_care."PoimenStatus" AS ENUM ('NOT_STARTED', 'IN_PROGRESS', 'COMPLETE');
CREATE TYPE pastoral_care."SilentDriftStatus" AS ENUM ('FLAGGED', 'RESOLVED', 'ESCALATED');
CREATE TYPE pastoral_care."FollowUpTaskStatus" AS ENUM ('OPEN', 'ESCALATED', 'COMPLETED');

-- [BLUEPRINT-EXACT] Blueprint §7.4's `type` CHECK constraint, shown verbatim.
CREATE TYPE stewardship."FinancialTransactionType" AS ENUM (
  'OFFERING', 'TITHE', 'SPECIAL_OFFERING', 'PLEDGE', 'DONATION', 'EXPENSE'
);
CREATE TYPE stewardship."FinancialTransactionChannel" AS ENUM ('CASH', 'MOBILE_MONEY');
CREATE TYPE stewardship."ProjectStatus" AS ENUM ('ACTIVE', 'COMPLETED', 'CANCELLED');

CREATE TYPE gatherings."GatheringStatus" AS ENUM ('SCHEDULED', 'CANCELLED', 'COMPLETED');
-- [BLUEPRINT-EXACT] PRD §12.2: "a status (present, absent, excused)".
CREATE TYPE gatherings."AttendanceStatus" AS ENUM ('PRESENT', 'ABSENT', 'EXCUSED');

CREATE TYPE insights."AlertStatus" AS ENUM ('OPEN', 'ACTED', 'DISMISSED');
CREATE TYPE insights."PulseScoreScopeType" AS ENUM ('PERSON', 'GROUP', 'BRANCH');

CREATE TYPE platform."AuthMethod" AS ENUM ('PHONE_OTP', 'EMAIL_PASSWORD');
CREATE TYPE platform."AuthorizationEffect" AS ENUM ('ALLOW', 'DENY');

-- ===========================================================================
-- platform.councils / platform.branches
-- [PRD-DERIVED / BLUEPRINT-EXACT] FR-ADM-03; PRD §12.3's ERD:
-- COUNCIL ||--o{ BRANCH : oversees.
-- ===========================================================================

CREATE TABLE platform.councils (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name       TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE platform.branches (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  council_id UUID NOT NULL REFERENCES platform.councils (id) ON DELETE RESTRICT,
  name       TEXT NOT NULL,
  timezone   TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===========================================================================
-- people.groups - unifies Bacenta (PASTORAL_CARE) / Basonta (MINISTRY)
-- [BLUEPRINT-EXACT] PRD §12.6 - no Cluster type, no parent/child hierarchy.
-- ===========================================================================

CREATE TABLE people.groups (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id        UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  type             people."GroupType" NOT NULL,
  name             TEXT NOT NULL,
  -- [PRD-DERIVED] FR-PC-01 (Bacenta): name, leader, meeting schedule, location.
  meeting_schedule TEXT,
  meeting_location TEXT,
  -- [PRD-DERIVED] FR-MIN-01 (Basonta): name, leader, purpose/category.
  category         TEXT,
  lifecycle_status people."GroupLifecycleStatus" NOT NULL DEFAULT 'ACTIVE',
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX groups_branch_id_type_idx ON people.groups (branch_id, type);

-- ===========================================================================
-- people.persons
-- [BLUEPRINT-EXACT] Blueprint §7.2: "includes optional nullable
-- guardian_person_id".
-- ===========================================================================

CREATE TABLE people.persons (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id          UUID NOT NULL REFERENCES platform.branches (id) ON DELETE RESTRICT,
  first_name         TEXT NOT NULL,
  last_name          TEXT NOT NULL,
