  custom_fields      JSONB,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX persons_branch_id_idx ON people.persons (branch_id);
CREATE INDEX persons_guardian_person_id_idx ON people.persons (guardian_person_id);

