-- ===========================================================================
-- people.group_memberships - the temporal model
-- [BLUEPRINT-EXACT] Blueprint §7.5's exact DDL: started_at/ended_at,
-- required-on-close reason, partial unique index enforcing exactly one
-- active PASTORAL_CARE membership per person (BR-PPL-01).
-- ===========================================================================

CREATE TABLE people.group_memberships (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id  UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  person_id  UUID NOT NULL REFERENCES people.persons (id) ON DELETE CASCADE,
  group_id   UUID NOT NULL REFERENCES people.groups (id) ON DELETE CASCADE,
  group_type people."GroupType" NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at   TIMESTAMPTZ,
  reason     TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX group_memberships_person_id_started_ended_idx
  ON people.group_memberships (person_id, started_at, ended_at);
CREATE INDEX group_memberships_group_id_started_ended_idx
  ON people.group_memberships (group_id, started_at, ended_at);
CREATE INDEX group_memberships_branch_id_idx ON people.group_memberships (branch_id);

-- [BLUEPRINT-EXACT] Blueprint §7.5's exact partial unique index.
CREATE UNIQUE INDEX one_active_bacenta_per_person ON people.group_memberships (person_id)
  WHERE group_type = 'PASTORAL_CARE' AND ended_at IS NULL;

