-- ===========================================================================
-- stewardship.financial_transactions / financial_transaction_events
-- [BLUEPRINT-EXACT] Blueprint §7.4's full DDL, shown verbatim: header row
-- plus append-only event log, amount stored as amount_minor BIGINT.
-- ===========================================================================

CREATE TABLE stewardship.financial_transactions (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id       UUID NOT NULL REFERENCES platform.branches (id) ON DELETE RESTRICT,
  type            stewardship."FinancialTransactionType" NOT NULL,
  source_group_id UUID REFERENCES people.groups (id) ON DELETE SET NULL,
  giver_person_id UUID REFERENCES people.persons (id) ON DELETE SET NULL,
