CREATE TABLE stewardship.financial_transaction_events (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  transaction_id UUID NOT NULL REFERENCES stewardship.financial_transactions (id) ON DELETE CASCADE,
  from_state     TEXT,
