CREATE INDEX projects_branch_id_status_idx ON stewardship.projects (branch_id, status);

CREATE TABLE stewardship.pledges (
  id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id                UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  project_id               UUID NOT NULL REFERENCES stewardship.projects (id) ON DELETE CASCADE,
  person_id                UUID NOT NULL REFERENCES people.persons (id) ON DELETE CASCADE,
  pledged_amount_minor     BIGINT NOT NULL,
  currency                 CHAR(3) NOT NULL DEFAULT 'GHS',
  pledged_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  reminder_opt_in          BOOLEAN NOT NULL DEFAULT false,
  reminder_sent_at         TIMESTAMPTZ,
  fulfilled_transaction_id UUID REFERENCES stewardship.financial_transactions (id) ON DELETE SET NULL,
  created_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at               TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX pledges_project_id_idx ON stewardship.pledges (project_id);
CREATE INDEX pledges_person_id_idx ON stewardship.pledges (person_id);
CREATE INDEX pledges_branch_id_idx ON stewardship.pledges (branch_id);

-- ===========================================================================
-- insights.engagement_signals / pulse_scores / pulse_score_history / alerts
-- [PRD-DERIVED] PRD §12.8's flowchart; FR-INS-01/03/05.
-- ===========================================================================

CREATE TABLE insights.engagement_signals (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id   UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  -- person_id intentionally has no FK constraint - see
  -- db/schema.prisma's comment on EngagementSignal.personId.
  person_id   UUID,
  group_id    UUID REFERENCES people.groups (id) ON DELETE SET NULL,
  signal_type TEXT NOT NULL,
  payload     JSONB NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX engagement_signals_branch_id_type_occurred_idx
  ON insights.engagement_signals (branch_id, signal_type, occurred_at);
CREATE INDEX engagement_signals_person_id_idx ON insights.engagement_signals (person_id);

-- Current/latest score per scope; pulse_score_history holds the full time
-- series - see db/DESIGN_NOTES.md Open Question #7.
CREATE TABLE insights.pulse_scores (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id   UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  scope_type  insights."PulseScoreScopeType" NOT NULL,
  scope_id    UUID NOT NULL,
  score       DECIMAL(5, 2) NOT NULL,
  computed_at TIMESTAMPTZ NOT NULL,
  UNIQUE (scope_type, scope_id)
);

CREATE INDEX pulse_scores_branch_id_scope_type_idx ON insights.pulse_scores (branch_id, scope_type);

CREATE TABLE insights.pulse_score_history (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id   UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  scope_type  insights."PulseScoreScopeType" NOT NULL,
  scope_id    UUID NOT NULL,
  score       DECIMAL(5, 2) NOT NULL,
  computed_at TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX pulse_score_history_branch_scope_computed_idx
  ON insights.pulse_score_history (branch_id, scope_type, scope_id, computed_at);

CREATE TABLE insights.alerts (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id            UUID NOT NULL REFERENCES platform.branches (id) ON DELETE CASCADE,
  scope_type           insights."PulseScoreScopeType" NOT NULL,
  scope_id             UUID NOT NULL,
  alert_type           TEXT NOT NULL,
  message              TEXT,
  status               insights."AlertStatus" NOT NULL DEFAULT 'OPEN',
  resolved_by_person_id UUID REFERENCES people.persons (id) ON DELETE SET NULL,
  resolved_at          TIMESTAMPTZ,
  triggered_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX alerts_branch_id_status_idx ON insights.alerts (branch_id, status);

-- ===========================================================================
-- Row-Level Security (Blueprint §7.3)
--
-- Every Branch-scoped table gets RLS enabled with a policy comparing its
-- branch_id column to the current session's app.current_branch_id setting.
-- [BLUEPRINT-EXACT] Blueprint §7.3's exact policy expression:
--   USING (branch_id = current_setting('app.current_branch_id')::uuid)
-- with NO second `true` (missing_ok) argument to current_setting - the
-- first draft of this migration used `current_setting(..., true)`, which
-- silently returns NULL instead of raising when the session variable is
-- unset. The Blueprint's version hard-fails in that case, which is the
-- correct fail-closed behavior for a security backstop and has been
-- corrected here to match exactly.
--
-- This is a BACKSTOP under application-layer filtering (RBAC in
-- libs/rbac), not a replacement for it.
--
-- IMPORTANT, and not yet wired anywhere (see db/DESIGN_NOTES.md Open
-- Question #3): nothing in this migration sets app.current_branch_id, and
-- Postgres bypasses RLS entirely for the table owner unless FORCE ROW
-- LEVEL SECURITY is also set (deliberately not set here, since migrations
-- and seeding need to write cross-Branch data as the owning role). For RLS
-- to do anything at runtime, the application must connect as a different,
-- non-owner Postgres role, and a Prisma middleware/interceptor must run
-- `SET LOCAL app.current_branch_id = '<uuid>'` at the start of every
-- request-scoped transaction. Neither exists yet.
-- ===========================================================================

ALTER TABLE people.groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY groups_branch_isolation ON people.groups
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE people.persons ENABLE ROW LEVEL SECURITY;
CREATE POLICY persons_branch_isolation ON people.persons
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE people.role_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_assignments_branch_isolation ON people.role_assignments
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE people.group_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY group_memberships_branch_isolation ON people.group_memberships
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE platform.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY users_branch_isolation ON platform.users
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE platform.configurations ENABLE ROW LEVEL SECURITY;
CREATE POLICY configurations_branch_isolation ON platform.configurations
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

ALTER TABLE platform.audit_log ENABLE ROW LEVEL SECURITY;
