  USING (branch_id = current_setting('app.current_branch_id')::uuid);

-- Pastoral notes are the most sensitive data in this schema (PRD §17.3;
-- ADMIN is explicitly DENYed read access in libs/rbac's permission matrix
-- per NFR-PRIV-01). RLS here is a deliberate extra backstop even though it
-- is the same branch_id policy shape as every other table.
ALTER TABLE pastoral_care.pastoral_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY pastoral_notes_branch_isolation ON pastoral_care.pastoral_notes
  USING (branch_id = current_setting('app.current_branch_id')::uuid);

