-- financial_transaction_events has no direct branch_id column (Blueprint
-- §7.4's DDL doesn't include one on the event log) - scoped via a
-- subquery against its parent transaction instead.
ALTER TABLE stewardship.financial_transaction_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY financial_transaction_events_branch_isolation ON stewardship.financial_transaction_events
  USING (
    transaction_id IN (
      SELECT id FROM stewardship.financial_transactions
      WHERE branch_id = current_setting('app.current_branch_id')::uuid
    )
  );

