-- platform.branches itself: a row's own id, not a branch_id column, is
-- what's compared.
ALTER TABLE platform.branches ENABLE ROW LEVEL SECURITY;
CREATE POLICY branches_self_isolation ON platform.branches
  USING (id = current_setting('app.current_branch_id')::uuid);
